#!/usr/bin/env python3
"""A small, modeless UTF-8 terminal editor.

The buffer, input decoder, highlighter, and terminal renderer are deliberately
independent; none of them relies on an external editor or terminal UI package.
"""
import errno
import fcntl
import os
import re
import select
import signal
import struct
import sys
import termios
import time
import unicodedata
from dataclasses import dataclass

VERSION = '0.4.3'
ESC = '\x1b['
MAPPINGS = [
    ('Ctrl-Q                        ', 'Quit'),
    ('Ctrl-S                        ', 'Save to file'),
    ('Ctrl-O                        ', 'Open text buffer'),
    ('Ctrl-X                        ', 'Next text buffer'),
    ('Alt-X                         ', 'Previous text buffer'),
    ('Ctrl-P or UP                  ', 'Move cursor up'),
    ('Ctrl-N or DOWN                ', 'Move cursor down'),
    ('Ctrl-F or RIGHT               ', 'Move cursor right'),
    ('Ctrl-B or LEFT                ', 'Move cursor left'),
    ('Ctrl-A or Alt-LEFT or HOME    ', 'Move cursor to head of line'),
    ('Ctrl-E or Alt-RIGHT or END    ', 'Move cursor to end of line'),
    ('Ctrl-[ or Ctrl-V or PAGE DOWN ', 'Next page'),
    ('Ctrl-] or Alt-V or PAGE UP    ', 'Previous page'),
    ('Alt-F or Ctrl-RIGHT           ', 'Move cursor to next word'),
    ('Alt-B or Ctrl-LEFT            ', 'Move cursor to previous word'),
    ('Alt-N or Ctrl-DOWN            ', 'Move cursor to next paragraph'),
    ('Alt-P or Ctrl-UP              ', 'Move cursor to previous paragraph'),
    ('Alt-<                         ', 'Move cursor to top of file'),
    ('Alt->                         ', 'Move cursor to bottom of file'),
    ('Ctrl-H or BACKSPACE           ', 'Delete character'),
    ('Ctrl-D or DELETE              ', 'Delete next character'),
    ('Ctrl-W                        ', 'Delete a word'),
    ('Ctrl-J                        ', 'Delete until head of line'),
    ('Ctrl-K                        ', 'Delete until end of line'),
    ('Ctrl-U                        ', 'Undo last change'),
    ('Ctrl-R                        ', 'Redo last undo change'),
    ('Ctrl-G                        ', 'Search text'),
    ('Ctrl-M                        ', 'New line'),
    ('Ctrl-L                        ', 'Refresh screen'),
    ('Ctrl-?                        ', 'Show this help'),
]

def help_text(program):
    intro = f'''{program}: A tiny UTF-8 terminal text editor

Kiro is a tiny UTF-8 text editor on terminals for Unix-like systems.
Specify file paths to edit as a command argument or run without argument to
start to write a new text.
Help can show up with key mapping Ctrl-?.

Usage:
    {program} [options] [FILES...]

Mappings:
'''
    return intro + ''.join('    ' + k + ': ' + v + '\n' for k, v in MAPPINGS) + '''
Options:
    -v, --version       Print version
    -h, --help          Print this help

'''


def arguments(args):
    paths, options = [], []
    end = False
    for arg in args:
        if end or arg == '-' or not arg.startswith('-'):
            paths.append(arg)
        elif arg == '--':
            end = True
        elif arg.startswith('--'):
            name, eq, value = arg[2:].partition('=')
            if name not in ('version', 'help'):
                raise ValueError("Unrecognized option: '%s'" % name)
            if eq:
                raise ValueError("Option '%s' does not take an argument" % name)
            options.append(name[0])
        else:
            for ch in arg[1:]:
                if ch not in 'vh':
                    raise ValueError("Unrecognized option: '%s'" % ch)
                options.append(ch)
    return paths, options


def char_width(ch):
    code = ord(ch)
    if code == 0 or unicodedata.category(ch) in ('Mn', 'Me', 'Cf'):
        return 0
    if code < 32 or 127 <= code < 160:
        return -1
    if unicodedata.east_asian_width(ch) in ('W', 'F'):
        return 2
    return 1


def width(text):
    return sum(max(0, char_width(c)) for c in text)


def render_column(text, pos):
    col = 0
    for ch in text[:pos]:
        col += 8 - col % 8 if ch == '\t' else max(0, char_width(ch))
    return col


def word_class(ch):
    if ch.isspace():
        return 0
    return 1 if ch.isascii() and (ch.isalnum() or ch == '_') else 2


def error_string(e):
    if isinstance(e, UnicodeError):
        return 'stream did not contain valid UTF-8'
    if isinstance(e, OSError):
        return f'{os.strerror(e.errno)} (os error {e.errno})'
    return str(e)


def quoted_char(ch):
    if ch == '\r':
        return "'\\r'"
    if ch == '\n':
        return "'\\n'"
    return "'\\u{%x}'" % ord(ch)


EXTENSIONS = {
    'rs': 'rust', 'c': 'c', 'h': 'c',
    'cc': 'c++', 'cpp': 'c++', 'cxx': 'c++',
    'hh': 'c++', 'hpp': 'c++', 'hxx': 'c++',
    'py': 'python', 'js': 'javascript', 'go': 'go',
}

