            self.set_message('At least one file has unsaved changes! Press ^Q again to quit or ^S to save', True)
        else:
            self.quitting = False
            if kind == 'char':
                b.insert(char)
            elif kind == 'tab':
                b.insert('\t')
            elif kind == 'enter':
                b.newline()
            elif kind == 'backspace' or (kind == 'ctrl' and char == 'h'):
                b.backspace()
            elif kind == 'delete' or (kind == 'ctrl' and char == 'd'):
                b.delete_forward()
            elif kind == 'ctrl' and char in 'jkw':
                b.kill({'j':'head','k':'tail','w':'word'}[char])
