def arguments(args):
    paths, options = [], []
    end = False
    for arg in args:
        if end or arg == '-' or not arg.startswith('-'):
            paths.append(arg)
        elif arg == '--':
            end = True
        elif arg.startswith('--'):
            name, eq, value = arg[2:].partition('=')
            if name not in ('version', 'help'):
                raise ValueError("Unrecognized option: '%s'" % name)
            if eq:
                raise ValueError("Option '%s' does not take an argument" % name)
            options.append(name[0])
        else:
            for ch in arg[1:]:
                if ch not in 'vh':
                    raise ValueError("Unrecognized option: '%s'" % ch)
                options.append(ch)
    return paths, options


def char_width(ch):
    code = ord(ch)
    if code == 0 or unicodedata.category(ch) in ('Mn', 'Me', 'Cf'):
        return 0
    if code < 32 or 127 <= code < 160:
        return -1
    if unicodedata.east_asian_width(ch) in ('W', 'F'):
        return 2
    return 1


def width(text):
    return sum(max(0, char_width(c)) for c in text)


def render_column(text, pos):
    col = 0
    for ch in text[:pos]:
        col += 8 - col % 8 if ch == '\t' else max(0, char_width(ch))
    return col


def word_class(ch):
    if ch.isspace():
        return 0
    return 1 if ch.isascii() and (ch.isalnum() or ch == '_') else 2


def error_string(e):
    if isinstance(e, UnicodeError):
        return 'stream did not contain valid UTF-8'
    if isinstance(e, OSError):
        return f'{os.strerror(e.errno)} (os error {e.errno})'
    return str(e)


def quoted_char(ch):
    if ch == '\r':
        return "'\\r'"
    if ch == '\n':
        return "'\\n'"
    return "'\\u{%x}'" % ord(ch)


EXTENSIONS = {
    'rs': 'rust', 'c': 'c', 'h': 'c',
    'cc': 'c++', 'cpp': 'c++', 'cxx': 'c++',
    'hh': 'c++', 'hpp': 'c++', 'hxx': 'c++',
    'py': 'python', 'js': 'javascript', 'go': 'go',
}

# Lexical categories and declaration introducers, recorded from terminal colors.
LANGUAGES = {}

def language(name, groups, declarations):
    table = {}
    for color, words in groups.items():
