def highlight(lines, lang):
    """Return per-character lexical colors, carrying multi-line delimiters."""
    if lang not in LANGUAGES:
        return [[0] * len(line) for line in lines]
    words, declarations = LANGUAGES[lang]
    state = None
    result = []
    for line in lines:
        colors = [0] * len(line)
        i = 0
        naming = False
        while i < len(line):
            start = i
            if state:
                delimiter, category = state
                end = line.find(delimiter, i)
                if end < 0:
                    colors[i:] = [category] * (len(line) - i)
                    i = len(line)
                else:
                    i = end + len(delimiter)
                    colors[start:i] = [category] * (i - start)
                    state = None
                continue
            if (lang == 'python' and line[i] == '#') or (lang != 'python' and line.startswith('//', i)):
                colors[i:] = [246] * (len(line) - i)
                break
            if lang != 'python' and line.startswith('/*', i):
                end = line.find('*/', i + 2)
                if end < 0:
                    state = ('*/', 246)
                    end = len(line) - 2
                i = end + 2
                colors[start:i] = [246] * (i - start)
                continue
            triple = lang == 'python' and (line.startswith('"""', i) or line.startswith("'''", i))
            if triple:
                delim = line[i:i + 3]
                end = line.find(delim, i + 3)
                if end < 0:
                    state = (delim, 142)
                    i = len(line)
                else:
                    i = end + 3
                colors[start:i] = [142] * (i - start)
                continue
            if line[i] in "\"'" or (lang in ('go', 'javascript') and line[i] == '`'):
                quote = line[i]
                i += 1
                while i < len(line):
                    if line[i] == '\\':
                        i = min(len(line), i + 2)
                    elif line[i] == quote:
                        i += 1
                        break
                    else:
                        i += 1
                if quote == '`' and (i == len(line) and (not line.endswith('`') or i == start + 1)):
                    state = ('`', 142)
                colors[start:i] = [142] * (i - start)
                continue
            if line[i].isascii() and (line[i].isalpha() or line[i] == '_'):
                i += 1
                while i < len(line) and line[i].isascii() and (line[i].isalnum() or line[i] == '_'):
                    i += 1
                word = line[start:i]
                category = words.get(word, 0)
                if not category and naming:
                    category = 214
                    naming = False
                if word in declarations:
                    naming = True
                colors[start:i] = [category] * (i - start)
