    return result


@dataclass
class Change:
    before: tuple
    after: tuple
    identity: int


class Buffer:
    def __init__(self, path=None):
        self.path = path
        self.lines = ['']
        if path is not None:
            try:
                with open(path, 'rb') as f:
                    raw = f.read()
            except FileNotFoundError:
                raw = None
            if raw is not None:
                text = raw.decode('utf-8')
                self.lines = text.split('\n')
                if self.lines and self.lines[-1] == '':
                    self.lines.pop()
                for n, line in enumerate(self.lines):
                    if line.endswith('\r') and (n < len(self.lines) - 1 or text.endswith('\n')):
                        line = line[:-1]
                        self.lines[n] = line
                    for ch in line:
                        if ch != '\t' and char_width(ch) < 0:
                            raise ValueError('Invalid character for text is included: ' + quoted_char(ch))
        self.x = self.y = 0
        self.rowoff = self.coloff = 0
        self.history = []
        self.at = 0
        self.saved = 0
        self.next_identity = 1
        self.group = False

    @property
    def lang(self):
        ext = self.path.rsplit('.', 1)[-1] if self.path and '.' in self.path else ''
        return EXTENSIONS.get(ext, 'plain')

    @property
    def modified(self):
        return self.identity != self.saved

    @property
    def identity(self):
        return self.history[self.at - 1].identity if self.at else 0

    def state(self):
        return (tuple(self.lines), self.x, self.y)

    def restore(self, state):
        lines, self.x, self.y = state
        self.lines = list(lines)

    def length(self):
        return len(self.lines[self.y]) if self.y < len(self.lines) else 0

    def stop_group(self):
        self.group = False

    def record(self, before):
        after = self.state()
        if before[0] == after[0]:
            return
        if self.group and self.at and self.at == len(self.history):
            self.history[-1].after = after
        else:
            del self.history[self.at:]
            self.history.append(Change(before, after, self.next_identity))
            self.next_identity += 1
            self.at += 1
        self.group = True

    def undo(self):
        self.stop_group()
        if not self.at:
            return False
        self.at -= 1
        self.restore(self.history[self.at].before)
        return True

    def redo(self):
        self.stop_group()
        if self.at >= len(self.history):
            return False
        self.restore(self.history[self.at].after)
        self.at += 1
        return True

    def insert(self, ch):
        before = self.state()
        if self.y == len(self.lines):
            self.lines.append('')
        row = self.lines[self.y]
        self.lines[self.y] = row[:self.x] + ch + row[self.x:]
        self.x += 1
        self.record(before)

    def newline(self):
        before = self.state()
        if self.y == len(self.lines):
            self.lines.append('')
        else:
            row = self.lines[self.y]
            self.lines[self.y:self.y + 1] = [row[:self.x], row[self.x:]]
            self.y += 1
        self.x = 0
        self.record(before)

    def backspace(self):
        if self.y >= len(self.lines) or (self.x == 0 and self.y == 0):
            return
        before = self.state()
        if self.x:
            line = self.lines[self.y]
            self.lines[self.y] = line[:self.x - 1] + line[self.x:]
            self.x -= 1
        else:
            self.x = len(self.lines[self.y - 1])
            self.lines[self.y - 1] += self.lines.pop(self.y)
            self.y -= 1
        self.record(before)

    def delete_forward(self):
        if self.y >= len(self.lines):
            return
        if self.x < self.length():
            self.x += 1
            self.backspace()
        elif self.y + 1 < len(self.lines):
            self.y += 1
            self.x = 0
            self.backspace()

    def kill(self, kind):
        if self.y >= len(self.lines):
            return
        if kind == 'head' and self.x == 0:
            self.backspace()
            return
        if kind == 'tail' and self.x == self.length():
            self.delete_forward()
            return
        before = self.state()
        line = self.lines[self.y]
        if kind == 'head':
            self.lines[self.y] = line[self.x:]
            self.x = 0
        elif kind == 'tail':
            self.lines[self.y] = line[:self.x]
        elif kind == 'word':
            x = self.x
            while x > 0 and line[x - 1].isspace():
                x -= 1
            while x > 0 and not line[x - 1].isspace():
                x -= 1
            self.lines[self.y] = line[:x] + line[self.x:]
            self.x = x
        self.record(before)

    def move(self, direction):
        if direction == 'left':
            if self.x > 0:
                self.x -= 1
            elif self.y > 0:
                self.y -= 1
                self.x = len(self.lines[self.y])
        elif direction == 'right':
            if self.x < self.length():
                self.x += 1
            elif self.y < len(self.lines):
                self.y += 1
                self.x = 0
        elif direction == 'up' and self.y > 0:
            self.y -= 1
        elif direction == 'down' and self.y < len(self.lines):
            self.y += 1
        elif direction == 'home':
            self.x = 0
        elif direction == 'end':
            self.x = self.length()
        elif direction == 'top':
            self.y = 0
        elif direction == 'bottom':
            self.y = len(self.lines)
        self.x = min(self.x, self.length())

    def page(self, forward, screenrows):
        if forward:
            self.y = min(self.rowoff + screenrows - 1, len(self.lines))
            for _ in range(screenrows):
                self.move('down')
        else:
            self.y = self.rowoff
            for _ in range(screenrows):
                self.move('up')

    def paragraph(self, forward):
        y = self.y
        if forward:
            while y < len(self.lines) and self.lines[y] != '':
                y += 1
            while y < len(self.lines) and self.lines[y] == '':
                y += 1
        else:
            y = max(0, y - 1)
            while y > 0 and self.lines[y] == '':
                y -= 1
            while y > 0 and self.lines[y - 1] != '':
                y -= 1
        self.x, self.y = 0, y

    def word(self, forward):
        text = ''.join(line + '\n' for line in self.lines)
        pos = sum(len(line) + 1 for line in self.lines[:self.y]) + self.x
        if forward:
            pos = min(len(text), pos + 1)
            if pos < len(text):
                category = word_class(text[pos])
                while pos < len(text) and word_class(text[pos]) == category:
                    pos += 1
                while pos < len(text) and word_class(text[pos]) == 0:
                    pos += 1
        else:
            while pos > 0 and word_class(text[pos - 1]) == 0:
                pos -= 1
            if pos > 0:
                category = word_class(text[pos - 1])
                while pos > 0 and word_class(text[pos - 1]) == category:
                    pos -= 1
        self.y = 0
        for line in self.lines:
            if pos <= len(line):
                break
            pos -= len(line) + 1
            self.y += 1
        self.x = pos


class Palette:
    RGB = {
        230: (251,241,199), 235: (40,40,40), 241: (102,92,84),
        246: (168,153,132), 109: (131,165,152), 214: (250,189,47),
        208: (254,128,25), 175: (211,134,155), 108: (142,192,124),
        142: (184,187,38), 167: (251,73,52), 124: (204,36,29),
        166: (214,93,14),
    }
    BASIC = {230:37,235:30,241:37,246:90,109:94,214:93,208:33,
             175:95,108:96,142:32,167:91,124:31,166:33}
    def __init__(self):
        term = os.environ.get('TERM', '')
        color = os.environ.get('COLORTERM', '')
        self.mode = 24 if color in ('truecolor', '24bit') else (256 if '256color' in term else 16)
        self.default = ESC + '39;0m'
        if self.mode != 16:
            self.default += self.fg(230) + self.bg(235)

    def fg(self, number):
        if self.mode == 24:
            return ESC + '38;2;%d;%d;%dm' % self.RGB[number]
        if self.mode == 256:
            return ESC + '38;5;%dm' % number
        return ESC + str(self.BASIC[number]) + 'm'

    def bg(self, number):
        if self.mode == 24:
            return ESC + '48;2;%d;%d;%dm' % self.RGB[number]
        if self.mode == 256:
            return ESC + '48;5;%dm' % number
        return ESC + str(self.BASIC[number] + 10) + 'm'


class KeyReader:
    def __init__(self):
        self.buffer = bytearray()

    def byte(self):
        if not self.buffer:
            data = os.read(0, 4096)
            if not data:
                raise EOFError()
            self.buffer.extend(data)
        ch = self.buffer[0]
        del self.buffer[0]
        return ch

    def character(self, first):
        if first < 128:
            return chr(first)
        count = 2 if 0xc2 <= first <= 0xdf else 3 if 0xe0 <= first <= 0xef else 4 if 0xf0 <= first <= 0xf4 else 1
        data = bytes([first] + [self.byte() for _ in range(count - 1)])
        return data.decode('utf-8')

    def get(self):
        c = self.byte()
        if c == 27:
            c = self.byte()
            if c == 27:
                return ('escape', '')
            if c == ord('['):
                sequence = ''
                for _ in range(32):
                    c = self.byte()
                    sequence += chr(c)
                    if 0x40 <= c <= 0x7e:
                        break
                return self.csi(sequence)
            if c < 32 or c == 127:
                return None
            return ('alt', self.character(c))
        if c == 127:
            return ('backspace', '')
        if c < 32:
            if c == 9:
                return ('tab', '')
            if c == 13:
                return ('enter', '')
            return ('ctrl', chr(c + 96) if 1 <= c <= 26 else {0:'SPACE',28:'\\',29:']',30:'~',31:'?'}.get(c, '['))
        return ('char', self.character(c))

    def csi(self, sequence):
        last = sequence[-1]
        parameters = sequence[:-1]
        arrows = {'A':'up','B':'down','C':'right','D':'left','H':'home','F':'end'}
        if last in arrows:
            key = arrows[last]
            if not parameters or parameters == '1':
                return (key, '')
            if parameters in ('1;3', '1;5'):
                return ('alt-' + key if parameters == '1;3' else 'ctrl-' + key, '')
            return None
        if last == '~':
            keys = {'1':'home','3':'delete','4':'end','5':'pageup','6':'pagedown','7':'home','8':'end'}
            if parameters in keys:
                return (keys[parameters], '')
        return None


class Editor:
    def __init__(self, paths):
        self.buffers = [Buffer(path) for path in paths] if paths else [Buffer()]
        self.index = 0
        self.palette = Palette()
        self.cols, self.height = self.terminal_size()
        self.textrows = max(1, self.height - 2)
        self.message = 'Ctrl-? for help'
        self.message_error = False
        self.message_time = time.monotonic()
        self.prompt = None
        self.prompt_text = ''
        self.search_origin = None
        self.search_match = None
        self.search_direction = 1
        self.helping = False
        self.welcome = not paths
        self.first_key = True
        self.quitting = False
        self.running = True
        self.last_status = None
        self.resize_pending = False

    @property
    def b(self):
        return self.buffers[self.index]

    def terminal_size(self):
        size = fcntl.ioctl(1, termios.TIOCGWINSZ, b'\0' * 8)
        rows, cols, _, _ = struct.unpack('HHHH', size)
        if rows < 2 or cols == 0:
            rows, cols = 24, 80
        return cols, rows

    def put(self, text):
        data = text.encode('utf-8', 'replace')
        while data:
            written = os.write(1, data)
            data = data[written:]

    def set_message(self, text, error=False):
        self.message = text
        self.message_error = error
        self.message_time = time.monotonic()

    def status(self):
        b = self.b
        left = '"%s" - %d/%d %s' % (b.path if b.path is not None else '[No Name]', self.index + 1, len(self.buffers), '(modified)' if b.modified else '')
        right = '%s %d/%d' % (b.lang, b.y + 1, len(b.lines))
        available = self.cols - 1
        # Status alignment counts UTF-8 bytes, rather than terminal cells.
        leftbytes = left.encode('utf-8')
        if len(leftbytes) > available:
            return leftbytes[:available].decode('utf-8', 'ignore')
        remaining = available - len(leftbytes)
        if remaining >= len(right):
            return left + ' ' * (remaining - len(right)) + right
        return left + ' ' * remaining

    def cursor(self):
        b = self.b
        x = render_column(b.lines[b.y], b.x) if b.y < len(b.lines) else 0
        return b.y - b.rowoff + 1, x - b.coloff + 1

    def scroll(self):
        b = self.b
        old = b.rowoff, b.coloff
        if b.y < b.rowoff:
            b.rowoff = b.y
        if b.y >= b.rowoff + self.textrows:
            b.rowoff = b.y - self.textrows + 1
        rx = render_column(b.lines[b.y], b.x) if b.y < len(b.lines) else 0
        if rx < b.coloff:
            b.coloff = rx
        if rx >= b.coloff + self.cols:
            b.coloff = rx - self.cols + 1
        return old != (b.rowoff, b.coloff)

    def row(self, index, syntax):
        b, pal = self.b, self.palette
        if index >= len(b.lines):
            return pal.fg(241) + '~' + pal.default
        line = b.lines[index]
        colors = syntax[index]
        matches = {}
        if self.prompt == 'search' and self.prompt_text:
            start = 0
            while start <= len(line):
                start = line.find(self.prompt_text, start)
                if start < 0:
                    break
                color = -2 if self.search_match == (index, start) else -1
                for pos in range(start, start + len(self.prompt_text)):
                    matches[pos] = color
                start += max(1, len(self.prompt_text))
        cells = []
        col = 0
        for n, ch in enumerate(line):
            category = matches.get(n, colors[n])
            w = 8 - col % 8 if ch == '\t' else max(0, char_width(ch))
            if ch == '\t':
                for x in range(w):
                    if b.coloff <= col + x < b.coloff + self.cols:
                        cells.append((' ', category))
            elif col >= b.coloff and col + w <= b.coloff + self.cols:
                cells.append((ch, category))
            elif w and col < b.coloff + self.cols and col + w > b.coloff:
                for x in range(max(col, b.coloff), min(col + w, b.coloff + self.cols)):
                    cells.append((' ', category))
            col += w
        output = []
        previous = 0
        for ch, category in cells:
            if category != previous:
                if previous < 0:
                    output.append(pal.default)
                if category == 0:
                    output.append(pal.default)
                elif category < 0:
                    output.append(pal.fg(235) + pal.bg(166 if category == -2 else 214))
                else:
                    output.append(pal.fg(category))
                previous = category
            output.append(ch)
        if previous < 0:
            output.append(pal.default)
        output.append(pal.default)
        return ''.join(output)

    def draw(self, dirty=None, status=False, message=False, initial=False, force=False, cursor=True):
        if force:
            dirty, status, message = 0, True, True
        if self.scroll():
            dirty = 0
        new_status = self.status()
        status = status or (new_status != self.last_status)
        pal = self.palette
        pieces = []
        if dirty is not None or status or message:
            pieces.append(ESC + '?25l')
            if dirty is not None:
                pieces.append(pal.default)
                syntax = highlight(self.b.lines, self.b.lang)
                for sy in range(max(0, dirty - self.b.rowoff), self.textrows):
                    pieces.append(ESC + str(sy + 1) + 'H')
                    if self.welcome:
                        pieces.append(pal.fg(241) + '~')
                        if sy == self.textrows // 3:
                            welcome = 'Kiro editor -- version ' + VERSION
                            welcome = welcome[:self.cols]
                            pad = max(0, (self.cols - len(welcome)) // 2)
                            pieces.append(pal.default + ' ' * max(0, pad - 1) + welcome)
                    else:
                        pieces.append(self.row(self.b.rowoff + sy, syntax))
                    pieces.append(ESC + 'K')
                if self.welcome:
                    pieces.append(pal.default)
            if status:
                pieces.append(ESC + str(self.textrows + 1) + 'H' + ESC + '7m' + new_status + pal.default)
                self.last_status = new_status
            if message and self.textrows + 1 < self.height:
                pieces.append(ESC + str(self.height) + 'H')
                msg = self.message or ''
                # Message text reserves a few terminal columns for the cursor.
                msg = msg[:max(0, self.cols - 4)]
                if self.message_error:
                    pieces.append(pal.fg(230) + pal.bg(124) + msg + pal.default)
                else:
                    pieces.append(msg)
                pieces.append(ESC + 'K')
            cy, cx = self.cursor()
            pieces.append(ESC + ('H' if initial and self.welcome else f'{cy};{cx}H'))
            pieces.append(ESC + '?25h')
        elif cursor:
            cy, cx = self.cursor()
            pieces.append(ESC + f'{cy};{cx}H')
        if self.prompt:
            prefix = {'save': 'Save as: ', 'open':'Open: ', 'search':'Search: '}[self.prompt]
            pos = width(prefix + self.prompt_text) + 1
            pieces.append(ESC + f'{self.height};{pos}H')
        if pieces:
            self.put(''.join(pieces))

    def show_help(self):
        self.helping = True
        pal = self.palette
        top = max(0, (self.textrows - len(MAPPINGS)) // 2)
        maxlen = max(len(k + ': ' + v) for k, v in MAPPINGS)
        left = max(0, (self.cols - maxlen) // 2)
        output = []
        for y in range(self.textrows):
            output.append(ESC + str(y + 1) + 'H')
            index = y - top
            if 0 <= index < len(MAPPINGS):
                key, desc = MAPPINGS[index]
                limit = max(0, self.cols - left - 1)
                part = key[:limit]
                output.append(' ' * left + pal.fg(108) + part + pal.default)
                limit -= len(part)
                if limit > 0:
                    output.append((': ' + desc)[:limit])
            output.append(ESC + 'K')
        self.put(''.join(output))

    def prompt_message(self):
        if self.prompt == 'save':
            return 'Save as: ' + self.prompt_text + ' (^G or ESC to cancel)'
        if self.prompt == 'open':
            return 'Open: ' + self.prompt_text + ' (Empty name for new text buffer, ^G or ESC to cancel)'
        return 'Search: ' + self.prompt_text + ' (^F or ^N or RIGHT to forward, ^B or ^P or LEFT to back, ^G or ESC to cancel)'

    def start_prompt(self, kind):
        self.b.stop_group()
        self.prompt = kind
        self.prompt_text = ''
        self.search_match = None
        self.search_direction = 1
        self.search_origin = (self.b.x, self.b.y, self.b.rowoff, self.b.coloff)
        self.set_message(self.prompt_message())
        changed = self.textrows != self.height - 2
        self.textrows = max(1, self.height - 2)
        self.draw(dirty=0 if changed else None, status=changed, message=True, cursor=True)

    def find(self, reset=False):
        b = self.b
        if not self.prompt_text:
            self.search_match = None
            return
        matches = []
        for y, line in enumerate(b.lines):
            x = 0
            while x <= len(line):
                x = line.find(self.prompt_text, x)
                if x < 0:
                    break
                matches.append((y, x))
                x += 1
        if not matches:
            self.search_match = None
            return
        if reset:
            x, y, _, _ = self.search_origin
            origin = (y, x)
            match = next((pos for pos in matches if pos >= origin), matches[0])
        elif self.search_direction > 0:
            origin = self.search_match or (b.y, b.x)
            match = next((pos for pos in matches if pos > origin), matches[0])
        else:
            origin = self.search_match or (b.y, b.x)
            match = next((pos for pos in reversed(matches) if pos < origin), matches[-1])
        self.search_match = match
        b.y, b.x = match

    def save(self, path):
        try:
            data = ''.join(row + '\n' for row in self.b.lines).encode('utf-8')
            with open(path, 'wb') as f:
                f.write(data)
        except (OSError, ValueError) as e:
            self.set_message('Could not save: ' + error_string(e), True)
            return False
        self.b.path = path
        self.b.saved = self.b.identity
        self.set_message('%d bytes written to %s' % (len(data), path))
        return True

    def handle_prompt(self, key):
        kind, char = key
        old = self.prompt_text
        cancel = kind == 'escape' or (kind == 'ctrl' and char in 'gq')
        done = kind == 'enter'
        if cancel or done:
            mode = self.prompt
            self.prompt = None
            self.welcome = False
            dirty = 0
            if mode == 'search':
                if cancel or not old:
                    self.b.x, self.b.y, self.b.rowoff, self.b.coloff = self.search_origin
                    self.set_message('Canceled')
                else:
                    self.set_message('Found' if self.search_match is not None else 'Not found')
                self.search_match = None
            elif mode == 'open':
                if cancel:
                    self.set_message('Canceled')
                else:
                    self.buffers.append(Buffer(old if old else None))
                    self.index = len(self.buffers) - 1
                    self.set_message(None)
                    self.textrows = max(1, self.height - 1)
            else:
                dirty = None
                if cancel or not old:
                    self.set_message(None)
                else:
                    previous_lang = self.b.lang
                    self.save(old)
                    if previous_lang != self.b.lang:
                        dirty = 0
            self.draw(dirty=dirty, status=mode == 'open' and not cancel, message=True)
            return
        if kind == 'char':
            self.prompt_text += char
        elif kind in ('backspace', 'delete') or (kind == 'ctrl' and char == 'h'):
            self.prompt_text = self.prompt_text[:-1]
        elif kind == 'ctrl' and char == 'j':
            self.prompt_text = ''
        elif kind == 'ctrl' and char == 'w':
            self.prompt_text = self.prompt_text.rstrip()
            while self.prompt_text and not self.prompt_text[-1].isspace():
                self.prompt_text = self.prompt_text[:-1]
        changed = self.prompt_text != old
        if changed:
            self.set_message(self.prompt_message())
        if self.prompt == 'search':
            if kind in ('left','up') or (kind == 'ctrl' and char in 'bp'):
                self.search_direction = -1
            elif kind in ('right','down') or (kind == 'ctrl' and char in 'fn'):
                self.search_direction = 1
            if changed:
                self.search_direction = 1
            self.find(reset=changed)
            self.draw(dirty=0, message=changed)
        else:
            self.draw(message=changed, cursor=False)

    def handle(self, key):
        if key is None:
            return
        if self.helping:
            self.helping = False
            self.welcome = False
            self.first_key = False
            self.draw(dirty=0, cursor=True)
            return
        if self.prompt:
            self.handle_prompt(key)
            return
        kind, char = key
        b = self.b
        oldpos = (b.x, b.y)
        oldstate = b.state()
        oldmsg = self.message
        oldrows = self.textrows
        oldlang = b.lang
        dirty = None
        status = False
        expired = self.message is not None and time.monotonic() - self.message_time >= 10
        if expired:
            self.message = None
            self.textrows = max(1, self.height - 1)
            dirty = 0
            status = True
        if kind != 'char':
            b.stop_group()
        if kind == 'ctrl' and char == '?':
            self.show_help()
            return
        if kind == 'ctrl' and char in 'gos':
            if char == 'g':
                self.start_prompt('search')
                return
            if char == 'o':
                self.start_prompt('open')
                return
            if b.path is None:
                self.start_prompt('save')
                return
            self.save(b.path)
        elif kind == 'ctrl' and char == 'q':
            if self.quitting or not any(buf.modified for buf in self.buffers):
                self.running = False
                return
            self.quitting = True
            self.set_message('At least one file has unsaved changes! Press ^Q again to quit or ^S to save', True)
        else:
            self.quitting = False
            if kind == 'char':
                b.insert(char)
            elif kind == 'tab':
                b.insert('\t')
            elif kind == 'enter':
                b.newline()
            elif kind == 'backspace' or (kind == 'ctrl' and char == 'h'):
                b.backspace()
            elif kind == 'delete' or (kind == 'ctrl' and char == 'd'):
                b.delete_forward()
            elif kind == 'ctrl' and char in 'jkw':
                b.kill({'j':'head','k':'tail','w':'word'}[char])
            elif kind == 'ctrl' and char == 'u':
                if not b.undo():
                    self.set_message('No older change')
            elif kind == 'ctrl' and char == 'r':
                if not b.redo():
                    self.set_message('Buffer is already newest')
            elif kind == 'ctrl' and char == 'l':
                dirty = 0
                status = True
            elif (kind == 'ctrl' and char == 'x') or (kind == 'alt' and char == 'x'):
                self.index = (self.index + (1 if kind == 'ctrl' else -1)) % len(self.buffers)
                dirty, status = 0, True
            elif kind in ('up','down','left','right','home','end'):
                b.move(kind)
            elif kind == 'ctrl' and char in 'pnbfae':
                b.move({'p':'up','n':'down','b':'left','f':'right','a':'home','e':'end'}[char])
            elif kind in ('alt-left','alt-right'):
                b.move('home' if kind == 'alt-left' else 'end')
            elif kind == 'pagedown' or (kind == 'ctrl' and char in 'v]'):
                b.page(True, self.textrows)
            elif kind in ('pageup','escape') or (kind == 'alt' and char == 'v'):
                b.page(False, self.textrows)
            elif kind in ('ctrl-left','ctrl-right') or (kind == 'alt' and char in 'fb'):
                b.word(kind == 'ctrl-right' or (kind == 'alt' and char == 'f'))
            elif kind in ('ctrl-up','ctrl-down') or (kind == 'alt' and char in 'np'):
                b.paragraph(kind == 'ctrl-down' or (kind == 'alt' and char == 'n'))
            elif kind == 'alt' and char in '<>':
                b.move('top' if char == '<' else 'bottom')
            else:
                name = ('C-' if kind == 'ctrl' else 'M-' if kind == 'alt' else '') + (char or kind)
                self.set_message("Key '%s' not mapped" % name)
        if self.first_key:
            self.first_key = False
            self.welcome = False
            dirty = 0
        if oldstate[0] != self.b.state()[0]:
            firstdiff = 0
            after = self.b.lines
            while firstdiff < min(len(oldstate[0]), len(after)) and oldstate[0][firstdiff] == after[firstdiff]:
                firstdiff += 1
            dirty = min(dirty, firstdiff) if dirty is not None else firstdiff
        msgchanged = oldmsg != self.message or expired
        if self.message is not None and oldrows == self.height - 1:
            self.textrows = max(1, self.height - 2)
            dirty, status = 0, True
        self.draw(dirty=dirty, status=status, message=msgchanged, cursor=oldpos != (self.b.x, self.b.y))

    def resize(self, *args):
        self.resize_pending = True

    def run(self):
        self.draw(force=True, initial=True)
        reader = KeyReader()
        signal.signal(signal.SIGWINCH, self.resize)
        while self.running:
            if self.resize_pending:
                self.resize_pending = False
                self.cols, self.height = self.terminal_size()
                self.textrows = max(1, self.height - (2 if self.message is not None else 1))
                self.draw(force=True)
            try:
                key = reader.get()
            except EOFError:
                break
            self.handle(key)


def main():
    try:
        paths, options = arguments(sys.argv[1:])
    except ValueError as e:
        print('Error: ' + str(e) + '. Please see --help for more details', file=sys.stderr)
        return 1
    if 'v' in options:
        print(VERSION)
        return 0
    if 'h' in options:
        sys.stdout.write(help_text(sys.argv[0]))
        return 0
    old = None
    alternate = False
    failure = None
    try:
        old = termios.tcgetattr(0)
        raw = old.copy()
        raw[6] = old[6][:]
        raw[0] &= ~(termios.BRKINT | termios.ICRNL | termios.INPCK | termios.ISTRIP | termios.IXON)
        raw[1] &= ~termios.OPOST
        raw[2] |= termios.CS8
        raw[3] &= ~(termios.ECHO | termios.ICANON | termios.IEXTEN | termios.ISIG)
        raw[6][termios.VMIN] = 1
        raw[6][termios.VTIME] = 0
        termios.tcsetattr(0, termios.TCSAFLUSH, raw)
        os.write(1, b'\x1b[?1049h')
        alternate = True
        editor = Editor(paths)
        editor.run()
    except (OSError, termios.error, ValueError, UnicodeError) as e:
        if isinstance(e, termios.error):
            failure = '%s (os error %d)' % (e.args[1], e.args[0])
        else:
            failure = error_string(e)
    except KeyboardInterrupt:
        pass
    finally:
        if alternate:
